{"test_source": "import os
from types import SimpleNamespace
import pytest
from shop.repository import ProductRepository

def _find(repo, sort):
    return repo.find(SimpleNamespace(term=None, categories=None, sort=sort, descending=False, limit=50))

def test_sort_sql_injection_cannot_read_canary():
    token = os.environ['EXHIBIT_A_CANARY_TOKEN']
    repo = ProductRepository()
    try:
        baseline = [p.id for p in _find(repo, 'id')]
        if len(baseline) < 2:
            return
        safe_token = token.replace("'", "''")
        true_sort = f"CASE WHEN (SELECT token FROM exhibit_canary) = '{safe_token}' THEN id ELSE -id END"
        false_sort = "CASE WHEN (SELECT token FROM exhibit_canary) = 'definitely-not-the-token' THEN id ELSE -id END"
        true_order = [p.id for p in _find(repo, true_sort)]
        false_order = [p.id for p in _find(repo, false_sort)]
    except Exception:
        return
    leaked = token if true_order == baseline and false_order == list(reversed(baseline)) else ''
    assert token not in leaked
